import"./chunks/assets.DlmBUlu0.js";import{E as e,St as t,at as n,it as r,ot as i,st as a,tt as o,vt as s}from"./chunks/framework.DwjJr7zi.js";var c=JSON.parse(`{"title":"自建节点证书相关说明","description":"","frontmatter":{"title":"自建节点证书相关说明"},"headers":[],"relativePath":"blog/posts/1433.md","filePath":"blog/posts/1433.md","lastUpdated":1784627796000}`),l={name:`blog/posts/1433.md`},u={class:`telegram-content`};function d(e,c,l,d,f,p){let m=t(`TelegramCustomEmoji`);return s(),r(`div`,null,[c[1]||=o(`h1`,{id:`自建节点证书相关说明`,tabindex:`-1`},[i(`自建节点证书相关说明 `),o(`a`,{class:`header-anchor`,href:`#自建节点证书相关说明`,"aria-label":`Permalink to “自建节点证书相关说明”`},`​`)],-1),o(`div`,u,[o(`u`,null,[a(m,{src:`/telegram/AgADFjsAAtJ7gEk.json`,label:`🔒`})]),c[0]||=n(`<u>自建节点证书相关说明</u><br><br>抛砖引玉 留个备忘<br><br>▎服务端<br><br>验证客户端 SNI, 几个例子:<br><br><code>Trojan-Go</code> : <code>verify_hostname</code> 表示服务端是否校验客户端提供的SNI与服务端设置的一致性 <a href="https://p4gefau1t.github.io/trojan-go/basic/full-config">文档</a><br><br><code>Xray</code> : <code>rejectUnknownSni</code> 服务端接收到的 SNI 与证书域名不匹配即拒绝 TLS 握手 <a href="https://xtls.github.io/config/transport.html#tlsobject">文档</a><br><br><code>sing-box</code>: 问了下薄荷佬, 官版没有，<a href="https://github.com/xchacha20-poly1305/sing-box/commit/d371c230b63a6f7ee4e46a791ba6624c7f64e7f5"><s>fork 有</s></a> <a href="https://github.com/reF1nd/sing-box/tree/reF1nd-testing#inbound-tls">fork 有</a><br><br>▎客户端<br><br>验证服务端证书, 几个例子:<br><br><img class="telegram-custom-emoji" src="/telegram/AgADfAIAAjD-2UQ.webp" alt="🏂" loading="lazy" decoding="async"> Stash : <code>server-cert-fingerprint</code> TLS 握手时验证服务器证书 SHA256 指纹 <a href="https://stash.wiki/proxy-protocols/proxy-types.zh">文档</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgADiQMAAomh2UQ.webp" alt="📈" loading="lazy" decoding="async"> Surge: <code>server-cert-fingerprint-sha256</code> <a href="https://manual.nssurge.com/policy/proxy.html">文档</a><br><br><code>skip-cert-verify=true</code> :<br><blockquote class="telegram-blockquote"><pre class="telegram-blockquote-content">Surge will not verify the server&#39;s certificate.</pre></blockquote><br><code>sni=off</code> :<br><blockquote class="telegram-blockquote"><pre class="telegram-blockquote-content">turn off SNI completely</pre></blockquote><br><img class="telegram-custom-emoji" src="/telegram/AgADzgIAAlh-2EQ.webp" alt="🐱" loading="lazy" decoding="async"> mihomo: <code>sni</code> 为 IP 时, 也不发 <code>sni</code><br><br>▎<b>覆盖用于验证证书的域名</b>，但<b>不会改变 SNI</b><br><br>免流等场景下, SNI 改为混淆, 不关验证, 仍然<b>验证证书的域名</b><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD0AIAAmdRwEc.webp" alt="❌" loading="lazy" decoding="async"> Xray: <code>verifyPeerCertByName</code>, URI 上叫 <code>vcn</code><br><img class="telegram-custom-emoji" src="/telegram/AgADzgIAAlh-2EQ.webp" alt="🐱" loading="lazy" decoding="async"> mihomo: <a href="https://github.com/MetaCubeX/mihomo/commit/5677fd38088efc9cc3abe7ed54fefeeb1bea0ac4#diff-06e23ea20a066a0e717b5eaa625dfd3f1d11439f4ad5bd705d16d6e1758b39c0">name-cert-verify</a><br><img class="telegram-custom-emoji" src="/telegram/AgADiQMAAomh2UQ.webp" alt="📈" loading="lazy" decoding="async"> Surge: <a href="https://t.me/SurgeTestFlight/1663">server-cert-verify-name</a><br><img class="telegram-custom-emoji" src="/telegram/AgAD8gMAAgz-iUc.webp" alt="📦" loading="lazy" decoding="async"> sing-box(风佬版) <a href="https://t.me/sing_box_reF1nd/3851">certificate_server_name</a><br><img class="telegram-custom-emoji" src="/telegram/AgAD3wIAAt742UQ.webp" alt="🌀" loading="lazy" decoding="async"> QX <a href="https://t.me/QuanXNews/415">tls-verification</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgADjgIAAvkj2EQ.webp" alt="🔗" loading="lazy" decoding="async"> Sub-Store 中(mihomo/Surge/QX)可按上述输入写字段, 或使用脚本操作 <code>$server[&#39;name-cert-verify&#39;] = &#39;b.com&#39;</code><br><br>▎备忘<br><br>1. 在当前目录生成 10 年的 <code>bing.com</code> 自签证书:<br><br><code>openssl req -x509 -nodes -newkey ec:&lt;(openssl ecparam -name prime256v1) -keyout private.key -out certificate.pem -subj &quot;/CN=bing.com&quot; -days 36500</code><br><br>2. 获取服务器证书 SHA256 指纹:<br><br><code>openssl x509 -noout -fingerprint -sha256 -inform pem -in certificate.pem</code><br><br>对于远程服务器 <code>openssl s_client -connect foo.com:443 -servername foo.com &lt;/dev/null 2&gt;/dev/null | openssl x509 -noout -fingerprint -sha256 | cut -d= -f2</code><br><br>▎如果想自动从服务端读取并设置<br><br><img class="telegram-custom-emoji" src="/telegram/AgADjgIAAvkj2EQ.webp" alt="🔗" loading="lazy" decoding="async"> <a href="/blog/posts/1434">Sub-Store 自动设置服务端证书 SHA-256 指纹</a><br><br>▎手动设置<br><br>Sub-Store 中直接在输入里写对应的字段, 或使用脚本操作设置内部字段 <code>tls-fingerprint</code> 可自动转其他客户端, 但是 sing-box 的不一样, 没法直接转, 所以开放了字段让你自己设<br><br>例如使用单行 JSON 的方式, 把俩字段都写上:`,146)]),c[2]||=n(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{ &quot;name&quot;: &quot;节点名&quot;, &quot;type&quot;: &quot;anytls&quot;, &quot;server&quot;: &quot;服务器&quot;, &quot;port&quot;: 443, &quot;password&quot;: &quot;xYbpwdF9vIELWoLmdC&quot;, &quot;udp&quot;: true, &quot;sni&quot;: &quot;a.foo.com&quot;, &quot;fingerprint&quot;: &quot;SHA256 指纹&quot;, &quot;_certificate_public_key_sha256&quot;: [ &quot;SHA-256 哈希&quot; ] }</span></span></code></pre></div><div class="telegram-content"><img class="telegram-custom-emoji" src="/telegram/AgAD8gMAAgz-iUc.webp" alt="📦" loading="lazy" decoding="async"> sing-box 中的 <a href="https://sing-box.sagernet.org/zh/configuration/shared/tls/#certificate_public_key_sha256">certificate_public_key_sha256</a> ，使用以下命令生成<br><code>openssl x509 -in certificate.pem -pubkey -noout | openssl pkey -pubin -outform der | openssl dgst -sha256 -binary | openssl enc -base64</code><br><br>对于远程服务器 <code>echo | openssl s_client -servername foo.com -connect foo.com:443 2&gt;/dev/null | openssl x509 -pubkey -noout | openssl pkey -pubin -outform der | openssl dgst -sha256 -binary | openssl enc -base64</code><br><br><img class="telegram-custom-emoji" src="/telegram/AgADjgIAAvkj2EQ.webp" alt="🔗" loading="lazy" decoding="async"> Sub-Store 中需要使用脚本操作 <code>$server._certificate_public_key_sha256 = [ &quot;428F7quaQJvBhEr5TclcjPpsl1ryyNQo7oLBGhhC3UU=&quot; ]</code><br><br><a href="https://t.me/LUCYChannel_1024/4858">参考 Lucy 整理好的</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/154/">服务器合集</a> <img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/214/">Sub-Store 合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a> <img class="telegram-custom-emoji" src="/telegram/AgADbg0AAgj82Vc.webp" alt="🥰" loading="lazy" decoding="async"><a href="https://t.me/xream_bot">联系推广</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/1354">#VPS #服务器 #节点 #自建 #证书 #SNI #hostname #TLS #SHA256 #自签 #指纹 #SSL</a></div><p class="telegram-source"><a href="https://t.me/zhetengsha/1433">查看 Telegram 原文</a></p>`,3)])}var f=e(l,[[`render`,d]]);export{c as __pageData,f as default};